const node = await figma.getNodeByIdAsync('2:16');
function walk(n, depth) {
  const out = {
    type: n.type, name: n.name, x: Math.round(n.x), y: Math.round(n.y),
    w: Math.round(n.width), h: Math.round(n.height),
    fills: n.fills, characters: n.characters, fontName: n.fontName, fontSize: n.fontSize,
    vectorPaths: n.vectorPaths
  };
  if (n.children && depth < 4) out.children = n.children.map(c => walk(c, depth + 1));
  return out;
}
return JSON.stringify(walk(node, 0), null, 2);

