const col = await figma.variables.createVariableCollection('MAC · Tokens');
const mode = col.modes[0].modeId;
function v(name, val, type) {
  const variable = figma.variables.createVariable(name, col, type || 'COLOR');
  variable.setValueForMode(mode, val);
  return variable;
}
const vars = {
  brandInk: v('brand/ink', INK),
  brandLime: v('brand/lime', LIME),
  surfacePage: v('surface/page', OFFWHITE),
  surfaceCard: v('surface/card', WHITE),
  surfaceMuted: v('surface/muted', GRAY_100),
  borderSubtle: v('border/subtle', GRAY_200),
  borderStrong: v('border/strong', GRAY_300),
  textPrimary: v('text/primary', INK),
  textSecondary: v('text/secondary', GRAY_600),
  textMuted: v('text/muted', GRAY_500),
  textInverse: v('text/inverse', WHITE),
};
return Object.keys(vars).length + ' variables created';

