const sourceIds = [
  '1:28', // Button
  '2:16', // Logo_MAC
  '2:13', '2:14', '2:15', '2:17', // social
  '2:2', '2:3', '2:4', '2:5', '2:6', '2:7', '2:8', '2:9', '2:10', '2:11', '2:12' // icons
];
const copies = {};
let cx = 40, cy = 40;
for (const id of sourceIds) {
  const src = await figma.getNodeByIdAsync(id);
  if (!src) { copies[id] = 'MISSING'; continue; }
  const c = src.clone();
  lib.appendChild(c);
  c.x = cx; c.y = cy;
  cx += c.width + 40;
  if (cx > 2200) { cx = 40; cy += 120; }
  copies[id] = c.id;
}
return JSON.stringify(copies);

